from datetime import datetime, timedelta

class CalendarUtil:
    SLOT_DURATION_MINUTES = 60
    DAY_START_HOUR = 0
    DAY_START_MINUTE = 0
    DAY_END_HOUR = 23
    DAY_END_MINUTE = 59

    def __init__(self):
        self._events = []

    @property
    def events(self):
        return list(self._events)

    def _set_events(self, events):
        self._events = list(events)

    def add_event(self, event):
        self._events.append(event)

    def remove_event(self, event):
        if event in self._events:
            self._events.remove(event)

    def get_events(self, date):
        return self._filter_events_by_date(date)

    def _filter_events_by_date(self, date):
        return [event for event in self._events if event['date'].date() == date.date()]

    def is_available(self, start_time, end_time):
        return not self._has_conflict(start_time, end_time)

    def _has_conflict(self, start_time, end_time):
        return any(
            start_time < event['end_time'] and end_time > event['start_time']
            for event in self._events
        )

    def get_available_slots(self, date):
        start_time = self._create_day_start_time(date)
        end_time = self._create_day_end_time(date)
        return self._generate_available_slots(start_time, end_time)

    def _create_day_start_time(self, date):
        return datetime(date.year, date.month, date.day, self.DAY_START_HOUR, self.DAY_START_MINUTE)

    def _create_day_end_time(self, date):
        return datetime(date.year, date.month, date.day, self.DAY_END_HOUR, self.DAY_END_MINUTE)

    def _generate_available_slots(self, start_time, end_time):
        available_slots = []
        while start_time < end_time:
            slot_end_time = start_time + timedelta(minutes=self.SLOT_DURATION_MINUTES)
            if self.is_available(start_time, slot_end_time):
                available_slots.append((start_time, slot_end_time))
            start_time += timedelta(minutes=self.SLOT_DURATION_MINUTES)
        return available_slots

    def get_upcoming_events(self, num_events):
        now = datetime.now()
        return self._filter_upcoming_events(num_events, now)

    def _filter_upcoming_events(self, num_events, now):
        upcoming_events = []
        for event in self._events:
            if event['start_time'] >= now:
                upcoming_events.append(event)
                if len(upcoming_events) == num_events:
                    break
        return upcoming_events
